import React, {  useRef } from 'react';


import CursorParticles from './CursorParticles/CursorParticles';

import 'bootstrap/dist/css/bootstrap.min.css';
import profileImage from '../images/profileimage.png';
import './Hello3D.css';



const Hello3D = () => {
  const heroRef = useRef(null); // Reference for the hero section

  const navigateToGitHub = () => {
    window.open('https://github.com/Imercenary27', '_blank');
  };

  return (
    <div className="main-container">
      <header className="hero-header" ref={heroRef}>
        <CursorParticles 
          containerRef={heroRef}
          particleCount={60}
          radius={120}
          spring={0.2}
          damping={0.88}
          baseOpacity={0.85}
        />
        <h1>Welcome to My Portfolio</h1>
        <p>
          Hi, I am Rajat Amate, a software developer passionate about solving real-world problems with innovative solutions.
        </p>
        <button className="cta-button" onClick={navigateToGitHub}>Learn More</button>
      </header>
      
      <div className="content-section">
        <div className="text-3d-section">
          <p className="about-text">
            <h1>About Me</h1>
            I am a software developer with expertise in web development and artificial intelligence. My mission is to create impactful solutions that make a difference.
            A Graduate Student of Bachelors of Engineering form Vidyalankar Institute of Technology
            CGPI 9.76
            Advent Love for Technology and stuff.
          </p>
        </div>
        <div className="profile-section">
          <img src={profileImage} alt="Profile" className="profile-image" />
        </div>
      </div>
    </div>
  );
};

export default Hello3D;
