import React from 'react'
import { motion } from 'framer-motion';
import Hello3D from './Hello3D';
import './Dashboard.css';
import Whyme from "./whyme"
import Projects from './Projects';
import Footer from "./Footer"
import Certification from './Certification';
import Contact from './Contact';
import MediumBlog from './MediumBlog';


const Dashboard = () => {



  const sectionVariants = {
      hidden: { opacity: 0, y: 50 },
      visible: { 
        opacity: 1, 
        y: 0,
        transition: { duration: 0.8, ease: "easeOut" }
      },exit: {
        opacity: 0,
        y: -50,
        transition: { duration: 0.5 }
      }
    };
  return (
    <div className="dashboard">
    <motion.section 
        id="home"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
      >
        
      <Hello3D />
    </motion.section>
    <motion.section
        id="whyme"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
        style={{ backgroundColor: 'white' }}
      >
     <Whyme/>
    </motion.section>
    <motion.section
        id="projects"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
      >
      <Projects/>
    </motion.section>
    <motion.section
        id="certifications"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.4 }}
      >
        <Certification/>
      </motion.section>
      <motion.section
        id="mywork"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
        style={{ backgroundColor: 'white' }}
      >
        <MediumBlog/>
      </motion.section>
    <motion.section
        id="contact"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.4 }}
      >
      <h2>Contact</h2>
      <Contact/>
    </motion.section>
    
    <div
        id="findme"
       
      >
     <Footer/>
     </div>
    
  </div>
  )
}

export default Dashboard;
