import { useRef, useState, useEffect, useCallback } from 'react';
import './cursorParticles.css';

class Particle {
  constructor(x, y) {
    this.origX = x;
    this.origY = y;
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.opacity = 0.8;
    
    // Confetti properties
    this.width = Math.random() * 8 + 4;  // Random width 4-12
    this.height = Math.random() * 12 + 6; // Random height 6-18
    this.rotation = Math.random() * Math.PI * 2; // Random initial rotation
    this.rotationSpeed = (Math.random() - 0.5) * 0.2; // Rotation speed
    this.color = this.getRandomColor(); // Random color
  }

  getRandomColor() {
    const colors = [
      '#ff6b6b', // Red
      '#4ecdc4', // Teal
      '#45b7d1', // Blue
      '#96ceb4', // Green
      '#feca57', // Yellow
      '#ff9ff3', // Pink
      '#54a0ff', // Light Blue
      '#5f27cd', // Purple
      '#00d2d3', // Cyan
      '#ff9f43', // Orange
      '#10ac84', // Emerald
      '#ee5a6f'  // Rose
    ];
    return colors[Math.floor(Math.random() * colors.length)];
  }

  update(cursorX, cursorY, radius, spring, damping) {
    const dx = cursorX - this.x;
    const dy = cursorY - this.y;
    const distance = Math.sqrt(dx ** 2 + dy ** 2);

    if (distance > 0) {
      const directionX = dx / distance;
      const directionY = dy / distance;
      const force = spring * Math.min(distance, 150);
      
      this.vx += directionX * force;
      this.vy += directionY * force;
    }

    const dxOrig = this.origX - this.x;
    const dyOrig = this.origY - this.y;
    const distOrig = Math.sqrt(dxOrig ** 2 + dyOrig ** 2);

    if (distOrig > radius) {
      const restoreForce = spring * 0.6 * (distOrig - radius) / distOrig;
      this.vx += dxOrig * restoreForce;
      this.vy += dyOrig * restoreForce;
    }

    this.vx *= damping;
    this.vy *= damping;
    
    const maxSpeed = 20;
    this.vx = Math.max(-maxSpeed, Math.min(this.vx, maxSpeed));
    this.vy = Math.max(-maxSpeed, Math.min(this.vy, maxSpeed));

    this.x += this.vx;
    this.y += this.vy;

    // Update rotation based on movement
    this.rotation += this.rotationSpeed + Math.abs(this.vx + this.vy) * 0.01;

    const speed = Math.sqrt(this.vx ** 2 + this.vy ** 2);
    this.opacity = Math.min(0.9, Math.max(0.4, speed / 8 + 0.3));
  }

  draw(ctx, baseOpacity) {
    ctx.save();
    
    // Move to particle position
    ctx.translate(this.x, this.y);
    
    // Apply rotation
    ctx.rotate(this.rotation);
    
    // Set color and opacity
    ctx.fillStyle = this.color;
    ctx.globalAlpha = this.opacity * baseOpacity;
    
    // Draw confetti rectangle (centered)
    ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);
    
    // Add a slight border for definition
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
    ctx.lineWidth = 0.5;
    ctx.strokeRect(-this.width / 2, -this.height / 2, this.width, this.height);
    
    ctx.restore();
  }
}

const CursorParticles = ({ 
  particleCount = 75,
  radius = 150,
  spring = 0.25,
  damping = 0.85,
  baseOpacity = 0.8,
  containerRef
}) => {
  const canvasRef = useRef(null);
  const [cursorPos, setCursorPos] = useState({ x: 0, y: 0 });
  const particles = useRef([]);

  const initParticles = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef?.current;
    if (!canvas || !container) return;

    const rect = container.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;
    
    particles.current = Array.from({ length: particleCount }, () => 
      new Particle(
        Math.random() * rect.width,
        Math.random() * rect.height
      )
    );
  }, [particleCount, containerRef]);

  const handleMouseMove = useCallback((e) => {
    const container = containerRef?.current;
    if (!container) return;

    const rect = container.getBoundingClientRect();
    setCursorPos({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    });
  }, [containerRef]);

  const animate = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    
    particles.current.forEach(particle => {
      particle.update(cursorPos.x, cursorPos.y, radius, spring, damping);
      particle.draw(ctx, baseOpacity);
    });

    requestAnimationFrame(animate);
  }, [cursorPos, radius, spring, damping, baseOpacity]);

  useEffect(() => {
    const container = containerRef?.current;
    if (!container) return;

    const resizeObserver = new ResizeObserver(() => {
      initParticles();
    });

    container.addEventListener('mousemove', handleMouseMove);
    resizeObserver.observe(container);

    initParticles();
    animate();

    return () => {
      container.removeEventListener('mousemove', handleMouseMove);
      resizeObserver.unobserve(container);
    };
  }, [animate, handleMouseMove, initParticles, containerRef]);

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        zIndex: 1
      }}
    />
  );
};

export default CursorParticles;
