import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './MediumBlog.css';

const useIsOverflow = (ref) => {
  const [isOverflow, setIsOverflow] = useState(false);

  useEffect(() => {
    const checkOverflow = () => {
      const { current } = ref;
      if (current) {
        const hasOverflow = current.scrollHeight > current.clientHeight;
        setIsOverflow(hasOverflow);
      }
    };

    checkOverflow();
    window.addEventListener('resize', checkOverflow);
    return () => window.removeEventListener('resize', checkOverflow);
  }, [ref]);

  return isOverflow;
};

const MediumBlog = ({ username }) => {
  const [posts, setPosts] = useState([]);
  const [expanded, setExpanded] = useState(false);
  const [loading, setLoading] = useState(true);
  const containerRef = useRef(null);
  const hasOverflow = useIsOverflow(containerRef);

  useEffect(() => {
    const fetchPosts = async () => {
      try {
        const response = await axios.get(
          `https://api.rss2json.com/v1/api.json?rss_url=https://medium.com/feed/@${"amaterajat67"}`
        );
        setPosts(response.data.items);
      } catch (error) {
        console.error('Error fetching Medium posts:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchPosts();
  }, [username]);

  if (loading) return <div className="loading">Loading posts...</div>;
  if (!posts.length) return <div className="error">No posts found.</div>;

  return (
    <section className="medium-blog">
      <h2>My Medium Stories</h2>
      <div 
        ref={containerRef}
        className={`posts-container ${expanded ? 'expanded' : ''}`}
      >
        <div className="posts-grid">
        {posts.map((post) => (
  <article key={post.guid} className="post-card">
    <a href={post.link} target="_blank" rel="noopener noreferrer">
      {post.thumbnail && (
        <img 
          src={post.thumbnail} 
          alt={post.title} 
          className="post-image"
        />
      )}
      <div className="card-content">
        <h3>{post.title}</h3>
        <div 
          className="post-excerpt" 
          dangerouslySetInnerHTML={{ __html: post.description }} 
        />
        <div className="post-meta">
          <span>{new Date(post.pubDate).toLocaleDateString()}</span>
          <span>· {post.categories.join(', ')}</span>
        </div>
      </div>
    </a>
    <button 
      className="card-button"
      onClick={() => window.open(post.link, '_blank')}
    >
      Read Article
      <svg className="button-icon" viewBox="0 0 24 24">
        <path d="M14 3v2h3.59l-9.83 9.83 1.41 1.41L19 6.41V10h2V3m-2 16H5V5h7V3H5c-1.11 0-2 .89-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7h-2v7z"/>
      </svg>
    </button>
  </article>
))}
        </div>
      </div>
      <a 
        href={`https://medium.com/@${"amaterajat67"}`}
        target="_blank"
        rel="noopener noreferrer"
        className="medium-link-button"
      >
        View All on Medium
      </a>
      {hasOverflow && (
        <button 
          className="expand-button"
          onClick={() => setExpanded(!expanded)}
        >
          {expanded ? 'Show Less' : 'Show More'}
          <span className={`arrow ${expanded ? 'up' : 'down'}`}></span>
        </button>
      )}
    </section>
  );
};

export default MediumBlog;
